CREATE proc [dbo].[uspInsertDineInOrder] @TiltId as int, @CounterId as int, @ShiftNo nvarchar(10), @Waiter nvarchar(50), @TableNo nvarchar(50),@cover int,@tab_unique_id as nvarchar(50),@order_type as nvarchar(50) ,@Customer as nvarchar(50),@Tele as nvarchar(50) as Declare @ShiftDate datetime; Declare @OrderTime nvarchar(50); Declare @OrderKey int; Declare @UserPunch nvarchar(50); Declare @TabUserPunch nvarchar(50); Declare @Order1 int; Declare @Order2 int; Declare @WaiterId int; Declare @UserId int;  select @WaiterId = id from Waiter where waiter_name = @Waiter and TiltId = @TiltId select @UserId = UserId from UserTiltAssign where TiltId = @TiltId and WaiterId = @WaiterId select @TabUserPunch = username from tbl_user where id = @UserId  SELECT @OrderTime = SUBSTRING(CONVERT(varchar, getdate(), 100), 13, 2) + ':' + SUBSTRING(CONVERT(varchar, getdate(), 100), 16, 2) + ' ' + SUBSTRING(CONVERT(varchar, getdate(), 100), 18, 2)  Select @ShiftDate = opening_date from Shift_Opening where status = 1 and z_report_number = @ShiftNo Select @Order1 = isnull(max(Od),0)+1 from Dine_In_Order select @Order2 = isnull(max(order_no),0)+1 from Dine_in_Order    insert into Dine_In_Order (order_key,z_number,order_type,order_no,order_date,[day], table_no,waiter_name,order_time,service_status,account_status, TiltId,UserPunch,Od,CounterId,TabUserPunch,cover,tab_unique_id,Tele,Customer) values ( '0',@ShiftNo,@order_type,@Order2,@ShiftDate,datename (dw,@ShiftDate),@TableNo,@Waiter,@OrderTime,'Open','Not Paid', @TiltId,@TabUserPunch,@Order1,@CounterId,@Waiter,@cover,@tab_unique_id,@Tele,@Customer ) set @OrderKey = scope_identity();  if (@OrderKey > 0) begin update Dine_In_Order set order_key = @OrderKey where id = @OrderKey update Tables set table_status = 'Open' where Tables = @TableNo end select @OrderKey;